def data(self, *keys):
    result = {}
    if not keys:
        return self.__dict__.copy()
    for key in keys:
        if isinstance(key, int):
            if key < 0 or key >= len(self.__dict__):
                raise IndexError(f"Index {key} is out of bounds")
            result[list(self.__dict__.keys())[key]] = list(self.__dict__.values())[key]
        else:
            result[key] = self.__dict__.get(key, None)
    return result

def pop_u16(self):
    if len(self.data) < 2:
        raise ValueError("Insufficient data to pop a 16-bit unsigned integer.")
    value = (self.data[-2] << 8) | self.data[-1]
    self.data = self.data[:-2]
    return value

