def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    try:
        from shapely.geometry import Point as BasePoint

        def __init__(self, *args, **kwargs):
            super().__init__(*args, **kwargs)
            for field, value in kwargs.items():
                if field in fields:
                    setattr(self, field, value)
            if 'srid' in kwargs and kwargs['srid'] in srid_map:
                self.srid = srid_map[kwargs['srid']]
            elif 'srid' in kwargs:
                raise ValueError(f"Invalid SRID: {kwargs['srid']} not in srid_map")

        new_class = type(name, (BasePoint,), {
            '__init__': __init__,
        })

        for field in fields:
            if not hasattr(new_class, field):
                setattr(new_class, field, None)

        return new_class
    except ImportError:
        raise ImportError("shapely library is required to use point_type function")
    except Exception as e:
        raise Exception(f"An error occurred: {str(e)}")

