def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    import subprocess
    import os
    from concurrent.futures import ThreadPoolExecutor

    if target_concurrency < 1:
        raise ValueError("target_concurrency must be at least 1")

    def run_command(args):
        try:
            result = subprocess.run(cmd + args, check=True, capture_output=True, text=False)
            return (result.returncode, result.stdout)
        except subprocess.CalledProcessError as e:
            return (e.returncode, e.stdout)

    # Split varargs into chunks for each concurrent process
    chunk_size = len(varargs) // target_concurrency + (1 if len(varargs) % target_concurrency else 0)
    chunks = [varargs[i:i + chunk_size] for i in range(0, len(varargs), chunk_size)]

    with ThreadPoolExecutor(max_workers=target_concurrency) as executor:
        results = list(executor.map(run_command, chunks))

    # Aggregate results, assuming success if all subcalls succeed
    aggregated_stdout = b''.join(result[1] for result in results)
    return_code = 0 if all(result[0] == 0 for result in results) else 1

    return (return_code, aggregated_stdout)

