def cached(cache, key=hashkey, lock=None):
    def decorator(func):
        def wrapper(*args, **kwargs):
            k = key(*args, **kwargs)
            try:
                with lock:
                    if k in cache:
                        return cache[k]
            except TypeError:
                pass  # lock is None or not a context manager
            except Exception as e:
                raise RuntimeError(f"An error occurred while accessing the cache: {e}")

            result = func(*args, **kwargs)
            try:
                with lock:
                    cache[k] = result
