            except Exception as e:
                raise RuntimeError(f"An error occurred while writing to the cache: {e}")
            return result
        return wrapper
    return decorator

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    from functools import lru_cache, wraps

    if maxsize is not None and not isinstance(maxsize, int):
        raise TypeError('Expected maxsize to be an integer or None')
    if maxsize < 0:
        raise ValueError('Expected maxsize to be a non-negative integer or None')
    if not isinstance(typed, bool):
        raise TypeError('Expected typed to be a bool')

    def decorator(func):
        cache = {}
        order = []

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = (args, kwargs) if not typed else (args, tuple(sorted(kwargs.items())))
            if key in cache:
                order.remove(key)
                order.append(key)
                return cache[key]
            result = func(*args, **kwargs)
            if len(cache) >= maxsize:
                oldest_key = order.pop(0)
                del cache[oldest_key]
            cache[key] = result
            order.append(key)
            return result

        def cache_clear():
            cache.clear()
            order.clear()

        def cache_info():
            return type('CacheInfo', (), {
                'hits': None,
                'misses': None,
                'maxsize': maxsize,
                'currsize': len(cache),
            })

        wrapper.cache_clear = cache_clear
        wrapper.cache_info = cache_info
        return wrapper

    return decorator

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """
    from functools import lru_cache as _lru_cache

    if not isinstance(maxsize, int) or maxsize < 0:
        raise ValueError("maxsize must be a non-negative integer or None")
    if not isinstance(typed, bool):
        raise ValueError("typed must be a boolean")

    def decorator(func):
        return _lru_cache(maxsize=maxsize, typed=typed)(func)

    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    from collections import defaultdict
    from functools import wraps

    def decorator(func):
        cache = {}
        frequency = defaultdict(int)
        if maxsize is not None:
            from heapq import heappush, heappop
            heap = []

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = args if typed else (args, tuple(sorted(kwargs.items())))
            if key in cache:
                frequency[key] += 1
                return cache[key]
            elif maxsize is None:
                result = func(*args, **kwargs)
                cache[key] = result
                return result
            else:
                if len(cache) < maxsize:
                    result = func(*args, **kwargs)
                    cache[key] = result
                    heappush(heap, (1, key))
                    frequency[key] = 1
                    return result
                else:
                    while heap:
                        count, k = heappop(heap)
                        if frequency[k] == count:
                            del cache[k]
                            del frequency[k]
                            break
                        else:
                            heappush(heap, (frequency[k], k))
                    result = func(*args, **kwargs)
                    cache[key] = result
                    heappush(heap, (1, key))
                    frequency[key] = 1
                    return result

        return wrapper

    return decorator

