def integral(bins, edges):
    if not isinstance(bins, (list, tuple)) or not isinstance(edges, (list, tuple)):
        raise ValueError("bins and edges must be lists or tuples")
    if len(bins) != len(edges) - 1:
        raise ValueError("len(bins) must be len(edges) - 1")

    try:
        return sum(b * (e2 - e1) for b, e1, e2 in zip(bins, edges, edges[1:]))
    except TypeError:
        raise ValueError("bins and edges must contain numerical values")

