            else:
                for i, obs in enumerate(observer):
                    if i >= len(last_applied_manifest):
                        last_applied_manifest.append(None)
                    if obs not in last_applied_manifest[i]:
                        last_applied_manifest[i] = obs
    except Exception as e:
        raise RuntimeError("An error occurred while updating the last applied manifest list") from e

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    for field, schema in observer_schema.items():
        if field not in response:
            raise KeyError(f"The observed field '{field}' is not present in the Kubernetes response")

        if isinstance(schema, dict) and isinstance(response[field], dict):
            if field not in last_applied_manifest:
                last_applied_manifest[field] = {}
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[field], schema, response[field]
            )
        else:
            if field not in last_applied_manifest:
                last_applied_manifest[field] = response[field]

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    try:
        if not app or not app.spec or not app.spec.manifest:
            raise ValueError("Invalid application or manifest")

        default_schema = {}
        for resource_type, resources in app.spec.manifest.items():
            if resource_type not in app.spec.observer_schema:
                default_schema[resource_type] = {}
                for resource_name, resource_details in resources.items():
                    default_schema[resource_type][resource_name] = {
                        "kind": resource_details.get("kind"),
                        "apiVersion": resource_details.get("apiVersion"),
                        "namespace": resource_details.get("metadata", {}).get("namespace"),
                        "name": resource_details.get("metadata", {}).get("name"),
                        "metrics": ["cpu_usage", "memory_usage"]  # Example default metrics
                    }
        return default_schema

    except Exception as e:
        raise RuntimeError(f"Failed to generate default observer schema: {e}")

def format(
    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
    contains the set of in-style parameters. It maps each parameter
    (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
    is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
    If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
    *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -   The formatted SQL query (:class:`str` or :class:`bytes`).

    -   The set of converted out-style parameters (:class:`dict` or
        :class:`list`).
    """
    try:
        in_style = self.SQLParams.in_style
        out_style = self.SQLParams.out_style
        if in_style == 'named':
            if isinstance(params, collections.abc.Mapping):
                if out_style == 'named':
                    return sql, dict(params)
                elif out_style == 'qmark':
                    qmark_sql = sql
                    new_params = []
                    for param in params:
                        qmark_sql = qmark_sql.replace(f':{param}', '?')
                        new_params.append(params[param])
                    return qmark_sql, new_params
                elif out_style == 'numeric':
                    numeric_sql = sql
                    new_params = []
                    for i, param in enumerate(params, start=1):
                        numeric_sql = numeric_sql.replace(f':{param}', f':{i}')
                        new_params.append(params[param])
                    return numeric_sql, new_params
                elif out_style == 'named_dollar':
                    named_dollar_sql = sql
                    for param in params:
                        named_dollar_sql = named_dollar_sql.replace(f':{param}', f'${{{param}}}')
                    return named_dollar_sql, dict(params)
                elif out_style == 'pyformat':
                    pyformat_sql = sql
                    for param in params:
                        pyformat_sql = pyformat_sql.replace(f':{param}', f'%({param})s')
                    return pyformat_sql, dict(params)
                else:
                    raise ValueError(f"Unsupported out-style: {out_style}")
            else:
                raise TypeError("params must be a Mapping for named in-style parameters")
        elif in_style == 'qmark':
            if isinstance(params, collections.abc.Sequence):
                if out_style == 'qmark':
                    return sql, list(params)
                elif out_style == 'numeric':
                    numeric_sql = sql
                    new_params = list(params)
                    for i in range(1, len(params) + 1):
                        numeric_sql = numeric_sql.replace('?', f':{i}')
                    return numeric_sql, new_params
                elif out_style == 'named':
                    raise ValueError("Cannot convert qmark in-style to named out-style without parameter names")
                elif out_style == 'named_dollar':
                    named_dollar_sql = sql
                    new_params = list(params)
                    for i in range(1, len(params) + 1):
                        named_dollar_sql = named_dollar_sql.replace('?', f'${{{i}}}')
                    return named_dollar_sql, new_params
                elif out_style == 'pyformat':
                    pyformat_sql = sql
                    new_params = list(params)
                    for i in range(1, len(params) + 1):
                        pyformat_sql = pyformat_sql.replace('?', f'%s')
                    return pyformat_sql, new_params
                else:
                    raise ValueError(f"Unsupported out-style: {out_style}")
            else:
                raise TypeError("params must be a Sequence for qmark in-style parameters")
        elif in_style == 'numeric':
            if isinstance(params, collections.abc.Sequence):
                if out_style == 'numeric':
                    return sql, list(params)
                elif out_style == 'qmark':
                    qmark_sql = sql
                    new_params = list(params)
                    for i in range(1, len(params) + 1):
                        qmark_sql = qmark_sql.replace(f':{i}', '?')
                    return qmark_sql, new_params
                elif out_style == 'named':
                    raise ValueError("Cannot convert numeric in-style to named out-style without parameter names")
                elif out_style == 'named_dollar':
                    named_dollar_sql = sql
                    new_params = list(params)
                    for i in range(1, len(params) + 1):
                        named_dollar_sql = named_dollar_sql.replace(f':{i}', f'${{{i}}}')
                    return named_dollar_sql, new_params
                elif out_style == 'pyformat':
                    pyformat_sql = sql
                    new_params = list(params)
                    for i in range(1, len(params) + 1):
                        pyformat_sql = pyformat_sql.replace(f':{i}', '%s')
                    return pyformat_sql, new_params
                else:
                    raise ValueError(f"Unsupported out-style: {out_style}")
            else:
                raise TypeError("params must be a Sequence for numeric in-style parameters")
        elif in_style == 'named_dollar':
            if isinstance(params, collections.abc.Mapping):
                if out_style == 'named_dollar':
                    return sql, dict(params)
                elif out_style == 'qmark':
                    qmark_sql = sql
                    new_params = []
                    for param in params:
                        qmark_sql = qmark_sql.replace(f'${{{param}}}', '?')
                        new_params.append(params[param])
                    return qmark_sql, new_params
                elif out_style == 'numeric':
                    numeric_sql = sql
                    new_params = []
                    for i, param in enumerate(params, start=1):
                        numeric_sql = numeric_sql.replace(f'${{{param}}}', f':{i}')
                        new_params.append(params[param])
                    return numeric_sql, new_params
                elif out_style == 'named':
                    named_sql = sql
                    for param in params:
                        named_sql = named_sql.replace(f'${{{param}}}', f':{param}')
                    return named_sql, dict(params)
                elif out_style == 'pyformat':
                    pyformat_sql = sql
                    for param in params:
                        pyformat_sql = pyformat_sql.replace(f'${{{param}}}', f'%({param})s')
                    return pyformat_sql, dict(params)
                else:
                    raise ValueError(f"Unsupported out-style: {out_style}")
            else:
                raise TypeError("params must be a Mapping for named_dollar in-style parameters")
        elif in_style == 'pyformat':
            if isinstance(params, collections.abc.Mapping):
                if out_style == 'pyformat':
                    return sql, dict(params)
                elif out_style == 'qmark':
                    qmark_sql = sql
                    new_params = []
                    for param in params:
                        qmark_sql = qmark_sql.replace(f'%({param})s', '?')
                        new_params.append(params[param])
                    return qmark_sql, new_params
                elif out_style == 'numeric':
                    numeric_sql = sql
                    new_params = []
                    for i, param in enumerate(params, start=1):
                        numeric_sql = numeric_sql.replace(f'%({param})s', f':{i}')
                        new_params.append(params[param])
                    return numeric_sql, new_params
                elif out_style == 'named':
                    named_sql = sql
                    for param in params:
                        named_sql = named_sql.replace(f'%({param})s', f':{param}')
                    return named_sql, dict(params)
                elif out_style == 'named_dollar':
                    named_dollar_sql = sql
                    for param in params:
                        named_dollar_sql = named_dollar_sql.replace(f'%({param})s', f'${{{param}}}')
                    return named_dollar_sql, dict(params)
                else:
                    raise ValueError(f"Unsupported out-style: {out_style}")
            else:
                raise TypeError("params must be a Mapping for pyformat in-style parameters")
        else:
            raise ValueError(f"Unsupported in-style: {in_style}")
    except Exception as e:
        raise ValueError(f"Error converting SQL parameters: {e}")

def formatmany(
    self,
    sql: AnyStr,
    many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    try:
        out_style_params = []
        if isinstance(many_params, Iterable):
            for params in many_params:
                if isinstance(params, Mapping):
                    # Assuming out-style is using named placeholders like :param
                    out_style_params.append({f":{key}": value for key, value in params.items()})
                elif isinstance(params, Sequence):
                    # Assuming out-style is using ordinal placeholders like ?
                    out_style_params.append([value for value in params])
        # Assuming out-style SQL uses ? for every placeholder
        out_sql = sql.replace('%s', '?').replace(':(', ':').replace(')', '')
        return out_sql, out_style_params
    except Exception as e:
        raise ValueError(f"Error formatting SQL and parameters: {e}")

