def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    try:
        new_args = []
        for expr in args:
            if isinstance(expr, tuple) and len(expr) == 3:
                op, left, right = expr
                if op == '&':
                    if right == (left, '|', right[2]) and isinstance(right, tuple) and len(right) == 3:
                        new_args.append(left)
                    elif right == ('~', left, '|', right[3]) and isinstance(right, tuple) and len(right) == 4:
                        new_args.append((op, left, right[3]))
                    else:
                        new_args.append(expr)
                elif op == '|':
                    if right == (left, '&', right[2]) and isinstance(right, tuple) and len(right) == 3:
                        new_args.append(left)
                    elif right == ('~', left, '&', right[3]) and isinstance(right, tuple) and len(right) == 4:
                        new_args.append((op, left, right[3]))
                    else:
                        new_args.append(expr)
                else:
                    new_args.append(expr)
            else:
                new_args.append(expr)
        return new_args
    except Exception as e:
        return args  # Return original args if any exception occurs

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.

    """
    def decorator(func):
        try:
            if not callable(func):
                raise ValueError("The provided handler must be callable.")
            if hook not in self._registry:
                self._registry[hook] = []
            self._registry[hook].append(func)
            return func
        except Exception as e:
            print(f"An error occurred while registering the handler: {e}")
            return func
    return decorator

def _fromutc(self, dt):
    if dt.tzinfo is None:
        raise ValueError("The datetime object must be timezone-aware.")

    try:
        # Convert the UTC datetime to the target timezone
        target_dt = dt.astimezone(self)

        # Check if the datetime is in a fold period
        fold = dt.replace(fold=1).astimezone(self) == target_dt
        return target_dt.replace(fold=fold)

    except Exception as e:
        raise ValueError(f"Error converting datetime: {e}")

