def next_version(version):
    try:
        # Split the version into components
        parts = version.split('.')
        # Convert each part to an integer, handling zero-prefixed numbers
        parts = [int(part, 10) for part in parts]
        # Increment the last part
        parts[-1] += 1
        # Join the parts back into a version string
        return '.'.join(map(str, parts))
    except ValueError:
        raise ValueError("Invalid version format. Please provide a version string in the format 'x.y.z...'.")

def validate_version_inventories(self, version_dirs):
    if not isinstance(version_dirs, list) or not all(isinstance(v, str) for v in version_dirs):
        raise ValueError("version_dirs must be a list of strings")

    root_inventory = self.get_root_inventory()  # Assuming this method exists to fetch the root inventory
    content_digests_diff = {}

    for version_dir in version_dirs:
        try:
            version_inventory = self.load_inventory(version_dir)  # Assuming this method exists to load inventory for a version
            if not version_inventory:
                raise ValueError(f"Inventory for version {version_dir} is empty or not found")

            for item, digest in version_inventory.items():
                if item not in root_inventory or root_inventory[item] != digest:
                    if version_dir not in content_digests_diff:
                        content_digests_diff[version_dir] = {}
                    content_digests_diff[version_dir][item] = digest

        except Exception as e:
            raise RuntimeError(f"Failed to validate inventory for version {version_dir}: {str(e)}")

    return content_digests_diff

def find_path_type(path):
    import os

    try:
        if not os.path.exists(path):
            return "Path does not exist"

        if os.path.isfile(path):
            return "file"

        if os.path.isdir(path):
            namaste_file_root = os.path.join(path, "0=ocfl_1.0")
            namaste_file_object = os.path.join(path, "0=ocfl_object_1.0")

            if os.path.isfile(namaste_file_root):
                return "root"
            elif os.path.isfile(namaste_file_object):
                return "object"
            else:
                return "Unknown OCFL type"

        return "Unknown path type"

    except Exception as e:
        return f"An error occurred: {str(e)}"

