def deep_merge_nodes(nodes):
    merged_dict = {}

    for key_node, value_node in nodes:
        key = key_node.value

        if key in merged_dict:
            existing_value_node = merged_dict[key]
            if isinstance(existing_value_node, ruamel.yaml.nodes.MappingNode) and isinstance(value_node, ruamel.yaml.nodes.MappingNode):
                existing_value_dict = dict(existing_value_node.value)
                value_dict = dict(value_node.value)
                merged_value_dict = deep_merge_nodes(list(existing_value_dict.items()) + list(value_dict.items()))
                value_node.value = merged_value_dict[key_node]
            else:
                # If there are colliding keys with non-MappingNode values, the last one wins
                merged_dict[key] = value_node
        else:
            merged_dict[key] = value_node

    return list(merged_dict.items())

