def deep_merge_nodes(nodes):
    from ruamel.yaml.nodes import MappingNode, ScalarNode

    def merge_values(key, value1, value2):
        if isinstance(value1, MappingNode) and isinstance(value2, MappingNode):
            merged_value = list(value1.value)
            value2_keys = {item[0].value for item in value2.value}
            for k, v in value1.value:
                if k.value in value2_keys:
                    for i, (k2, v2) in enumerate(value2.value):
                        if k2.value == k.value:
                            merged_value[i] = (k2, merge_values(k2.value, v, v2))
                            break
                else:
                    merged_value.append((k, v))
            for k, v in value2.value:
                if k.value not in value2_keys:
                    merged_value.append((k, v))
            return MappingNode(tag=value1.tag, value=merged_value)
        else:
            return value2

    merged_nodes = {}
    for key, value in nodes:
        if key.value in merged_nodes:
            merged_nodes[key.value] = merge_values(key.value, merged_nodes[key.value], value)
        else:
            merged_nodes[key.value] = value

    return [(ScalarNode(tag=key.tag, value=key_value), merged_nodes[key_value]) for key_value, key in merged_nodes.items()]

