def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import re
    import sys

    if platform == 'this':
        platform = 1 if sys.platform != 'win32' else 0

    if platform == 1:  # POSIX
        pattern = r"""(['"])(.*?)\1|\S+"""
    elif platform == 0:  # Windows/CMD
        pattern = r"""(["'])(?:(?=(\\?))\2.)*?\1|\S+"""
    else:
        raise ValueError("Unsupported platform value")

    try:
        return re.findall(pattern, s)
    except TypeError:
        raise ValueError("Input must be a string")

def addignored(ignored):
    try:
        # Run the git command to list ignored files
        result = subprocess.run(['git', 'check-ignore', '-v', ignored], capture_output=True, text=True, check=True)
        # Split the output into lines
        lines = result.stdout.splitlines()
        # Extract file names from each line
        ignored_files = [line.split()[2] for line in lines]
        # Sort the list of ignored files
        ignored_files.sort()
        # Join the sorted list into a single string separated by commas
        return ','.join(ignored_files)
    except subprocess.CalledProcessError as e:
        return f"Error: {e.stderr}"
    except Exception as e:
        return f"An error occurred: {str(e)}"

def match(filename):
    """
    Check if the filename is a type that this module supports

    Args:
        filename: Filename to match
    Returns:
        False if not a match, True if supported
    """
    try:
        if not isinstance(filename, str):
            return False
        # Example support for .txt and .md files
        supported_extensions = ('.txt', '.md')
        return any(filename.endswith(ext) for ext in supported_extensions)
    except Exception as e:
        return False

def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None

    try:
        value, unit = frequency.split()
        value = int(value)
    except (ValueError, TypeError):
        raise ValueError(f"Cannot parse frequency: {frequency}")

    units = {
        'seconds': 'seconds',
        'minutes': 'minutes',
        'hours': 'hours',
        'days': 'days',
        'weeks': 'weeks'
    }

    unit = unit.lower().rstrip('s')  # handle plural and singular forms
    if unit in units:
        return datetime.timedelta(**{units[unit]: value})

    raise ValueError(f"Unknown time unit: {unit}")

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        # Get the list of addresses for the hostname
        addresses = socket.getaddrinfo(host, None)
        # Check if any of the addresses is the loopback address
        for addr in addresses:
            if addr[4][0] in ('127.0.0.1', '::1'):
                return True
        return False
    except Exception:
        return False

def make_find_paths(find_paths):
    def is_pattern(s):
        return '*' in s or '?' in s or '[' in s or ']' in s

    transformed_paths = []
    for path in find_paths:
        try:
            if not is_pattern(path) and ':' not in path:
                transformed_paths.append(f'sh:**/*{path}*/**')
            else:
                transformed_paths.append(path)
        except Exception as e:
            print(f"Error processing path {path}: {e}")
            transformed_paths.append(path)
    return transformed_paths

