def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    '''
    try:
        config_dir = os.path.dirname(config_filename)
        if config_dir and not os.path.exists(config_dir):
            os.makedirs(config_dir)

        if os.path.exists(config_filename) and not overwrite:
            raise FileExistsError(f"File {config_filename} already exists and overwrite is False.")

        with open(config_filename, 'w', mode=mode) as file:
            file.write(rendered_config)

    except FileNotFoundError as e:
        print(f"File not found error: {e}")
    except PermissionError as e:
        print(f"Permission error: {e}")
    except FileExistsError as e:
        print(e)
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

def subprocess_run_helper(func, *args, timeout, extra_env=None):
    import subprocess
    import os
    import shutil
    import sys
    import importlib.util

    # Find the module and function name
    module_name = func.__module__
    function_name = func.__name__

    # Get the file path of the module
    spec = importlib.util.find_spec(module_name)
    if spec is None:
        raise ImportError(f"Module {module_name} not found.")
    module_path = spec.origin

    if module_path is None or module_path == 'built-in':
        raise ImportError(f"Module {module_name} is not an importable file.")

    # Create a temporary script to run the function
    temp_script_path = 'temp_subprocess_script.py'
    with open(temp_script_path, 'w') as temp_script:
        temp_script.write(f"from {module_name} import {function_name}\n")
        temp_script.write(f"{function_name}({', '.join(repr(arg) for arg in args)})"
                          if args else f"{function_name}()")

    try:
        # Set up the environment variables
        env = os.environ.copy()
        if extra_env:
            env.update(extra_env)

        # Run the subprocess
        result = subprocess.run(['python', temp_script_path], timeout=timeout, env=env, capture_output=True, text=True)

        # Remove the temporary script
        try:
            os.remove(temp_script_path)
        except Exception as e:
            print(f"Failed to remove temporary script: {e}")

        if result.returncode != 0:
            raise subprocess.CalledProcessError(result.returncode, result.args, result.stdout, result.stderr)

        return result.stdout

    except subprocess.TimeoutExpired as e:
        raise TimeoutError(f"Subprocess execution timed out: {e}") from e
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Subprocess failed with error: {e.stderr}") from e
    except Exception as e:
        raise Exception(f"An error occurred: {e}") from e
    finally:
        # Attempt to clean up the temporary script if it still exists
        if os.path.exists(temp_script_path):
            try:
                os.remove(temp_script_path)
            except Exception as e:
                print(f"Failed to remove temporary script in finally block: {e}")

