def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    try:
        mu = 0.2
        sigma = 0.1
        return np.exp(-0.5 * ((x - mu) / sigma) ** 2) / (sigma * np.sqrt(2 * np.pi))
    except Exception as e:
        print(f"An error occurred: {e}")
        return None

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import os
    import json
    import logging

    if overrides is None:
        overrides = {}

    config_dict = {}
    log_records = []

    def parse_config(filename):
        try:
            with open(filename, 'r') as file:
                config = json.load(file)
            if resolve_env:
                config = {k: os.path.expandvars(v) if isinstance(v, str) else v for k, v in config.items()}
            config.update(overrides)
            return config
        except Exception as e:
            record = logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0, 
                                     msg=str(e), args=(), exc_info=True)
            log_records.append(record)
            return None

    for filename in config_filenames:
        config = parse_config(filename)
        if config is not None:
            config_dict[filename] = config

    return config_dict, log_records

def from_ticks(cls, ticks, tz=None):
    if not (0 <= ticks < 86400000000000):
        raise ValueError("ticks is out of bounds (0 <= ticks < 86400000000000)")
    seconds, nanoseconds = divmod(ticks, 1000000000)
    minutes, seconds = divmod(seconds, 60)
    hours, minutes = divmod(minutes, 60)
    return cls(hours, minutes, seconds, nanoseconds, tzinfo=tz)

