def fromutc(self, dt):
    try:
        # Ensure the input is timezone-aware
        if dt.tzinfo is None:
            raise ValueError("Input datetime must be timezone-aware")

        # Calculate the offset to convert the datetime to UTC
        dt_utc = dt.astimezone(timezone.utc)

        # Convert the UTC datetime to the new timezone
        dt_new = dt_utc.astimezone(self)

        # Determine if the original datetime was in a fold state
        if dt.utcoffset() != dt.replace(fold=not dt.fold).utcoffset():
            dt_new = dt_new.replace(fold=dt.fold)

        return dt_new
    except Exception as e:
        raise ValueError(f"An error occurred: {e}")

