def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    import re
    tags = set()
    code_block = False
    lines = text.split('\n')
    replaced_text_lines = []

    for line in lines:
        # Check for code block delimiters
        if line.strip().startswith(''):
            code_block = not code_block

        if not code_block:
            # Find tags (words starting with '#')
            found_tags = re.findall(r'\B#\w\w+', line)
            for tag in found_tags:
                tags.add(tag[1:])  # Add tag without the '#'
                if replacer:
                    line = re.sub(re.escape(tag), replacer(tag), line)

        replaced_text_lines.append(line)

    replaced_text = '\n'.join(replaced_text_lines)
    return tags, replaced_text

def process_text_links(text):
    if not isinstance(text, str):
        raise ValueError("Input must be a string")

    import re

    def linkify(match):
        url = match.group(0)
        return f'<a href="{url}" target="_blank" rel="noopener noreferrer">{url}</a>'

    try:
        # Regular expression to match URLs
        url_pattern = re.compile(
            r'http[s]?://'  # http:// or https://
            r'(?:[a-zA-Z]|[0-9]|[$-_@.&+]|[!*\\(\\),]|'  # domain...
            r'(?:%[0-9a-fA-F][0-9a-fA-F]))+'  # ...percent-encoded chars
        )
        text = url_pattern.sub(linkify, text)
    except re.error as e:
        raise RuntimeError("Regex error occurred") from e

    return text

