def parse_diaspora_webfinger(document: str) -> Dict:
    import json
    from xml.etree import ElementTree as ET

    try:
        # Try parsing as JSON
        return json.loads(document)
    except json.JSONDecodeError:
        try:
            # Try parsing as XRD XML
            root = ET.fromstring(document)
            webfinger_data = {}
            for element in root.findall('{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link'):
                rel = element.get('rel')
                template = element.get('template')
                if rel and template:
                    webfinger_data[rel] = template
            return webfinger_data
        except ET.ParseError:
            raise ValueError("Document is neither valid JSON nor XRD XML")
    except Exception as e:
        raise ValueError(f"An error occurred: {str(e)}")

