    try:
        current = dic
        for k in (key,) + keys[:-1]:
            if k not in current or not isinstance(current[k], dict):
                current[k] = {}
            current = current[k]
        current[keys[-1]] = val
    except Exception as e:
        print(f"An error occurred: {e}")

