    except TypeError as e:
        raise ValueError("Arguments must be provided as a dictionary.") from e

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise ValueError("Arguments must be provided as a dictionary with keys 'value', 'min', and 'max'.")

    value = args.get('value')
    min_value = args.get('min')
    max_value = args.get('max')

    if value is None or min_value is None or max_value is None:
        raise ValueError("Arguments dictionary must contain 'value', 'min', and 'max' keys.")

    if not all(isinstance(i, (int, float)) for i in [value, min_value, max_value]):
        raise ValueError("The 'value', 'min', and 'max' must be numeric types.")

    if value < min_value or value > max_value:
        raise ValueError(f"Value {value} is not between {min_value} and {max_value}.")

    return True

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    if not isinstance(args, dict):
        raise ValueError("args must be a dictionary")

    for key, value in args.items():
        if key.startswith('control_'):
            control_args[key] = value
        elif key.startswith('custom_'):
            nested_args[key[len('custom_'):]] = value
        else:
            nested_args[key] = value

    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise ValueError("vars_dict must be a dictionary")

    if extra_vars is None:
        extra_vars = {}
    elif isinstance(extra_vars, list):
        extra_vars_dict = {}
        for item in extra_vars:
            if isinstance(item, str):
                try:
                    key, value = item.split('=', 1)
                    extra_vars_dict[key] = value
                except ValueError:
                    raise ValueError(f"Invalid extra-vars format: {item}")
            else:
                raise ValueError("All items in extra_vars list must be strings in 'key=value' format")
    elif isinstance(extra_vars, dict):
        extra_vars_dict = extra_vars
    else:
        raise ValueError("extra_vars must be a list of 'key=value' strings or a dictionary")

    vars_dict.update(extra_vars_dict)
    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import subprocess

    if not playbook_path:
        raise ValueError("playbook_path cannot be None")

    command = ['ansible-playbook', playbook_path]

    if verbose:
        command.extend(['-v'] * verbose)

    if extra_vars:
        if not isinstance(extra_vars, dict):
            raise ValueError("extra_vars must be a dictionary")
        extra_vars_str = ' '.join(f"{k}={v}" for k, v in extra_vars.items())
        command.extend(['-e', extra_vars_str])

    if ansible_args:
        if not isinstance(ansible_args, dict):
            raise ValueError("ansible_args must be a dictionary")
        for k, v in ansible_args.items():
            if v is None:
                command.append(f"--{k}")
            else:
                command.extend([f"--{k}", str(v)])

    try:
        result = subprocess.run(command, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        return result.stdout
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Ansible playbook failed with return code {e.returncode}\nError: {e.stderr}")

def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    try:
        if not isinstance(vars_dict, dict):
            raise ValueError("vars_dict must be a dictionary")
        if not isinstance(cli_args, list):
            raise ValueError("cli_args must be a list")
        if not ir_workspace or not isinstance(ir_workspace, type(ir_workspace)) or not hasattr(ir_workspace, 'path'):
            raise ValueError("ir_workspace must be a valid Infrared Workspace object")
        if not ir_plugin or not isinstance(ir_plugin, type(ir_plugin)) or not hasattr(ir_plugin, 'name'):
            raise ValueError("ir_plugin must be a valid InfraredPlugin object")

        extra_vars = ' '.join(f'{key}={value}' for key, value in vars_dict.items())
        command = ['ansible-playbook'] + cli_args + ['-e', extra_vars]
        result = ir_plugin.execute(command, workspace=ir_workspace.path)
        return result
    except Exception as e:
        return f"An error occurred: {str(e)}"

