def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    def flatten_dict(d, parent_key='', sep='_'):
        items = []
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(flatten_dict(v, new_key, sep=sep).items())
            else:
                items.append((new_key, v))
        return dict(items)

    try:
        spec_path = os.path.join(plugin_dir, 'plugin_spec.json')
        if not os.path.exists(spec_path):
            raise FileNotFoundError(f"plugin_spec.json not found in {plugin_dir}")

        with open(spec_path, 'r') as file:
            data = json.load(file)

        if not isinstance(data, dict):
            raise ValueError("plugin_spec.json does not contain a valid dictionary")

        return flatten_dict(data)

    except Exception as e:
        print(f"An error occurred: {e}")
        return {}

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    import os
    if 'CONFIG_PATH' not in os.environ:
        try:
            os.environ['CONFIG_PATH'] = '/path/to/default/config'
        except Exception as e:
            print(f"Failed to set CONFIG_PATH environment variable: {e}")

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    try:
        if not path.startswith(root):
            raise ValueError("Path does not start with the specified root.")
        return path[len(root):].lstrip('/')
    except Exception as e:
        raise Exception(f"Failed to remove root from path: {e}")
